-- Chạy bổ sung trên database Source đang dùng; không sửa hóa đơn/hợp đồng/tài khoản cũ.
-- Hangfire tự quản lý schema riêng `hangfire` khi API khởi động, không trộn với bảng nghiệp vụ.
BEGIN;
CREATE TABLE IF NOT EXISTS email_reminder_settings (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "Enabled" boolean NOT NULL DEFAULT false,
 "InvoiceEnabled" boolean NOT NULL DEFAULT true,
 "ContractEnabled" boolean NOT NULL DEFAULT true,
 "ContractDaysBefore" integer NOT NULL DEFAULT 7,
 "LastScanAt" timestamptz NULL,
 "CreatedAt" timestamptz NOT NULL, "CreatedBy" varchar(2000) NOT NULL, "IsArchived" boolean NOT NULL,
 CONSTRAINT ck_email_reminder_settings CHECK ("Id"=1 AND "ContractDaysBefore" BETWEEN 1 AND 90)
);
INSERT INTO email_reminder_settings ("Id","CreatedAt","CreatedBy","IsArchived") VALUES (1,NOW(),'schema-upgrade',false) ON CONFLICT ("Id") DO NOTHING;
CREATE TABLE IF NOT EXISTS email_reminders (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "DedupKey" varchar(200) NOT NULL, "Kind" varchar(30) NOT NULL, "EntityId" integer NOT NULL,
 "ContractId" integer NOT NULL REFERENCES contracts("Id") ON DELETE RESTRICT,
 "TenantId" integer NOT NULL REFERENCES tenants("Id") ON DELETE RESTRICT,
 "EventDate" date NOT NULL,
 "Recipient" varchar(254) NOT NULL DEFAULT '', "Subject" varchar(300) NOT NULL DEFAULT '',
 "Status" varchar(20) NOT NULL DEFAULT 'Pending', "Attempts" integer NOT NULL DEFAULT 0,
 "LastAttemptAt" timestamptz NULL, "SentAt" timestamptz NULL, "Error" varchar(500) NOT NULL DEFAULT '',
 "CreatedAt" timestamptz NOT NULL, "CreatedBy" varchar(2000) NOT NULL, "IsArchived" boolean NOT NULL,
 CONSTRAINT ck_email_reminder_kind CHECK ("Kind" IN ('InvoiceDue','ContractExpiry')),
 CONSTRAINT ck_email_reminder_status CHECK ("Status" IN ('Pending','Sending','Sent','Failed','Skipped','Uncertain','Cancelled') AND "Attempts">=0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_email_reminders_DedupKey" ON email_reminders("DedupKey");
CREATE INDEX IF NOT EXISTS "IX_email_reminders_ContractId" ON email_reminders("ContractId");
CREATE INDEX IF NOT EXISTS "IX_email_reminders_TenantId" ON email_reminders("TenantId");
COMMIT;
